// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/healthz", wrapper.GetLiveness)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/readyz", wrapper.GetReadiness)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/fs/list", wrapper.ListDirectory)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/authz/explain", wrapper.ExplainAccess)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/jobs/folder-size", wrapper.StartFolderSize)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/jobs", wrapper.ListJobs)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/jobs/{jobId}", wrapper.GetJob)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/jobs/{jobId}/cancel", wrapper.CancelJob)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/jobs/{jobId}/logs", wrapper.GetJobLogs)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/fs/mkdir", wrapper.CreateFolder)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/fs/rename", wrapper.RenameEntry)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/fs/transfer/plan", wrapper.PlanTransfer)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/jobs/transfer", wrapper.StartTransfer)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/fs/delete/plan", wrapper.PlanDelete)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/fs/trash", wrapper.MoveToTrash)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/jobs/delete", wrapper.StartPermanentDelete)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/trash", wrapper.ListTrash)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/trash/restore", wrapper.RestoreFromTrash)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/jobs/empty-trash", wrapper.StartEmptyTrash)
	})

	return r
}

